insert into public.attribute_categories(key,label,group_key,group_label,group_order,kind,weight,description,sort) values
('red_fruit','Red Fruit','fruit','Fruit',1,'aroma',1,'Bright, tart-to-sweet red berries and cherries — the signature of Pinot Noir, Gamay, Grenache and Sangiovese.',1),
('black_fruit','Black Fruit','fruit','Fruit',1,'aroma',1,'Dark, dense berries and stone fruit — Cabernet, Syrah, Malbec, Mourvèdre.',2),
('dried_fruit','Dried & Cooked Fruit','fruit','Fruit',1,'aroma',0.95,'Fruit transformed by sun, raisining, heat or time — Amarone, Port, warm-climate reds and aged wines.',3),
('citrus','Citrus','fruit','Fruit',1,'aroma',1,'Zest, juice and pith — Riesling, Sauvignon Blanc, Albariño, Champagne, young Chablis.',4),
('orchard_fruit','Orchard Fruit','fruit','Fruit',1,'aroma',1,'Apples, pears and quince — Chardonnay, Chenin Blanc, Champagne, Grüner.',5),
('stone_fruit','Stone Fruit','fruit','Fruit',1,'aroma',1,'Peaches, apricots and plums — Viognier, Riesling, Albariño, ripe Chardonnay.',6),
('tropical_fruit','Tropical Fruit','fruit','Fruit',1,'aroma',1,'Warm-climate and thiol-driven fruit — New World Sauvignon, Gewürztraminer, ripe Chardonnay.',7),
('green_fruit','Green Fruit','fruit','Fruit',1,'aroma',1,'Sharp, verdant fruit — Sauvignon Blanc, Vinho Verde, cool-climate whites.',8),
('floral','Floral','floral','Floral',2,'aroma',0.95,'Blossoms, petals and perfume — Nebbiolo, Muscat, Viognier, Riesling, Gewürztraminer.',9),
('green_vegetal','Green & Vegetal','herbal','Herbal & Vegetal',3,'aroma',0.9,'Pyrazines and green notes — Cabernet Franc, Sauvignon Blanc, cool-vintage Bordeaux.',10),
('herbs','Herbs','herbal','Herbal & Vegetal',3,'aroma',0.9,'Fresh and dried culinary herbs, the scrub of the Mediterranean — Rhône, Provence, Sicily, Napa.',11),
('savory_vegetal','Savory Leaf & Olive','herbal','Herbal & Vegetal',3,'aroma',0.9,'Olive, tea, hay and root — savoury, non-fruit character in reds and aged whites.',12),
('spice','Spice','spice','Spice',4,'aroma',0.95,'Pepper from rotundone, sweet spice from oak and grape — Syrah, Grüner, Zinfandel, Gewürz.',13),
('mineral','Mineral','earth','Earth & Mineral',5,'aroma',1,'Stone, chalk, salt and smoke-flint — the language of Chablis, Mosel, Sancerre, Etna, Santorini.',14),
('earth','Earth','earth','Earth & Mineral',5,'aroma',1,'Soil, forest floor and fungi — Burgundy, Barolo, Rioja, Northern Rhône, aged Bordeaux.',15),
('oak','Oak','cellar','Oak & Cellar',6,'aroma',0.9,'What the barrel gives — toast, vanilla, cedar, smoke and spice.',16),
('roast_confection','Roast & Confection','cellar','Oak & Cellar',6,'aroma',0.9,'Coffee, chocolate and caramel — ripe reds with oak, Port, PX, Amarone.',17),
('lees_malo','Lees & Malolactic','cellar','Oak & Cellar',6,'aroma',0.9,'Yeast autolysis and malolactic conversion — Champagne, white Burgundy, Muscadet sur lie.',18),
('tertiary','Tertiary','tertiary','Bottle Age',7,'aroma',1,'Evolution in bottle — leather, tobacco, game and honey; the reward of patience.',19),
('nutty_oxidative','Nut & Oxidative','tertiary','Bottle Age',7,'aroma',1,'Nuts, flor, rancio and noble rot — Sherry, Madeira, Tawny, Vin Jaune, Sauternes, Tokaji.',20),
('tannin_texture','Tannin Texture','texture','Texture',8,'texture',0.7,'Not how much tannin, but how it feels — the sommelier''s second question.',21),
('palate_texture','Palate Texture','texture','Texture',8,'texture',0.7,'Weight, shape and movement across the palate.',22),
('character','Character','style','Style & Character',9,'style',0.6,'The overall impression — how a sommelier would describe a wine''s personality.',23),
('winemaking','Winemaking','style','Style & Character',9,'style',0.6,'Cellar choices that shape style — élevage, method, intervention.',24),
('maturity_style','Ageing Profile','style','Style & Character',9,'style',0.6,'Where a wine sits in its life — and where it is headed.',25),
('structure','Structure','structure','Structure',10,'structure',1,'The architecture of a wine, on the WSET Systematic Approach scales.',26),
('pairing','At the Table','pairing','At the Table',11,'pairing',1,'Classic and inspired matches.',27)
